INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(1, 'Снятие напряжения затылочной области', 'Мягкое тракционное вытяжение шейно-затылочного перехода. Специалист подкладывает пальцы под затылок клиента и создаёт лёгкое тракционное усилие. Задержка 2–3 минуты. Позволяет снять компрессию в области большого затылочного отверстия, расслабить субокципитальные мышцы и уменьшить головное напряжение.', '', 1),
(1, 'Работа с лобными буграми', 'Лёгкое удержание лобных бугров двумя ладонями без давления. Специалист создаёт мягкий контакт и удерживает зону 1–2 минуты, следя за расслаблением тканей под руками. Снимает напряжение лобной зоны, помогает при тяжести в голове и усталости от зрительной нагрузки.', '', 2),
(1, 'Расслабление височных мышц', 'Мягкие круговые движения кончиками пальцев по височной зоне. Работа проводится без давления на виски — только скользящий контакт по мышцам. Помогает при сжатии в висках, напряжении от стресса и зубного сжатия.', '', 3),
(1, 'Техника CV4 (краниосакральная)', 'Мягкое удержание четвёртого желудочка через затылочную чешую. Специалист создаёт лёгкий контакт с затылком и сопровождает краниосакральный ритм до его замедления. Показана при головных болях напряжения, перегрузе нервной системы, хроническом стрессе.', '', 4);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(2, 'Мягкое расслабление лестничных мышц', 'Клиент лежит на спине, голова в нейтральном положении. Специалист мягко захватывает боковые поверхности шеи двумя руками и создаёт лёгкое растяжение без скручивания. Снимает гипертонус лестничных мышц, улучшает дыхание и освобождает плечевое сплетение.', '', 1),
(2, 'Тракция шейного отдела', 'Специалист удерживает голову клиента обеими руками и создаёт лёгкое осевое вытяжение вдоль позвоночника. Тракция мягкая, без рывков. Уменьшает компрессию межпозвонковых суставов, снимает напряжение разгибателей шеи.', '', 2),
(2, 'Мобилизация шейно-грудного перехода', 'Специалист фиксирует шейно-грудной переход двумя пальцами и мягко направляет движение вдох-выдох. Снимает застой в переходной зоне, улучшает подвижность нижних шейных сегментов.', '', 3),
(2, 'Расслабление трапециевидной мышцы', 'Мягкое захватывание верхней трапеции с умеренным давлением вниз и от шеи. Движение медленное, без резких нажатий. Снимает напряжение в зоне перехода шея-плечо, освобождает движение головы.', '', 4);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(3, 'Расслабление трапециевидной мышцы', 'Специалист работает с верхней и средней порцией трапеции продольными и поперечными движениями. Начинают с поверхностного контакта, постепенно углубляясь по мере расслабления тканей. Снимает хроническое напряжение плечевого пояса.', '', 1),
(3, 'Мобилизация плечевого сустава', 'Клиент лежит на спине. Специалист удерживает плечо и создаёт мягкие циркумдукционные движения в плечевом суставе в пределах безболезненного диапазона. Улучшает подвижность сустава, снимает мышечный спазм вокруг него.', '', 2),
(3, 'Работа с малой грудной мышцей', 'Специалист находит малую грудную мышцу под большой грудной и создаёт точечный контакт без давления. Удержание 30–60 секунд с последующим растяжением. Освобождает плечо от протракции, улучшает осанку и дыхание.', '', 3),
(3, 'Расслабление надостной мышцы', 'Мягкое давление в ямке лопатки над остью. Специалист находит болезненную точку и удерживает давление до расслабления. Снимает напряжение вращательной манжеты, уменьшает боль при подъёме руки.', '', 4);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(4, 'Мобилизация грудного отдела', 'Клиент лежит на спине, руки скрещены на груди. Специалист подкладывает кулак под грудной отдел и создаёт мягкий разгибательный импульс на выдохе. Снимает сгибательную ригидность грудного отдела, улучшает дыхание и осанку.', '', 1),
(4, 'Работа с ромбовидными мышцами', 'Специалист работает с зоной между лопатками продольными движениями вдоль волокон ромбовидных мышц. Снимает напряжение, которое формируется при длительном сидении и сутулости.', '', 2),
(4, 'Расслабление паравертебральных мышц', 'Продольные скользящие движения вдоль позвоночника в грудном отделе. Специалист работает от основания шеи к поясничному переходу медленными, равномерными движениями. Снимает общий гипертонус вдоль позвоночника.', '', 3),
(4, 'Освобождение подлопаточной зоны', 'Клиент лежит на боку. Специалист мягко подводит пальцы под медиальный край лопатки и создаёт контакт с подлопаточной мышцей. Удержание 1–2 минуты. Снимает глубокое напряжение за лопаткой, улучшает подвижность плеча.', '', 4);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(5, 'Расслабление квадратной мышцы поясницы', 'Клиент лежит на боку. Специалист находит квадратную мышцу поясницы между гребнем подвздошной кости и последним ребром и создаёт умеренное давление вдоль волокон. Снимает боковое напряжение поясницы.', '', 1),
(5, 'Мобилизация пояснично-крестцового перехода', 'Специалист удерживает крестец одной рукой и мягко направляет движение поясничного отдела на выдохе. Снимает блок в переходной зоне, уменьшает прострел и скованность.', '', 2),
(5, 'Работа с подвздошно-поясничной мышцей', 'Клиент лежит на спине, колени согнуты. Специалист медленно погружает пальцы в нижнебоковую часть живота и создаёт контакт с подвздошно-поясничной мышцей. Удержание 1–2 минуты без давления. Снимает глубокий сгибательный спазм поясницы.', '', 3),
(5, 'Диафрагмальное дыхание для поясницы', 'Специалист укладывает руки на нижние рёбра клиента и просит дышать в руки. На выдохе — лёгкое направление рёбер вниз и в стороны. 5–7 циклов. Расслабляет диафрагму, снимает напряжение с поясничной фасции.', '', 4);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(6, 'Расслабление диафрагмы', 'Специалист укладывает пальцы под нижние рёбра клиента и на выдохе мягко следует за движением рёбер. Задержка в фазе выдоха 2–3 секунды. Снимает диафрагмальный спазм, углубляет дыхание, снижает тревожное напряжение.', '', 1),
(6, 'Растяжение межрёберных мышц', 'Клиент поднимает руку вверх. Специалист мягко растягивает боковую поверхность грудной клетки продольным скользящим движением вдоль межреберий. Улучшает подвижность грудной клетки, снимает боль при дыхании.', '', 2),
(6, 'Работа с грудиной', 'Специалист кладёт ладонь на грудину без давления и сопровождает дыхательные движения. На выдохе — лёгкое направление грудины вниз. Снимает защитное напряжение передней поверхности тела.', '', 3),
(6, 'Расслабление большой грудной мышцы', 'Мягкая работа с большой грудной мышцей поперечными движениями от грудины к плечу. Снимает протракцию плеч, улучшает осанку и открывает грудную зону.', '', 4);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(8, 'Балансировка таза в положении лёжа', 'Клиент лежит на спине. Специалист укладывает руки под крестец и гребни подвздошных костей. Удержание без давления 2–3 минуты. Выравнивает положение таза, снимает асимметрию в тазобедренных суставах.', '', 1),
(8, 'Расслабление подвздошно-поясничной мышцы', 'Специалист находит мышцу в нижней части живота и создаёт мягкий контакт. Клиент дышит глубоко. Снимает сгибательный спазм таза, уменьшает перегрузку поясницы.', '', 2),
(8, 'Работа с приводящими мышцами бедра', 'Клиент лежит на спине, нога отведена в сторону. Специалист работает с медиальной поверхностью бедра продольными движениями от паха к колену. Снимает напряжение медиального компартмента.', '', 3),
(8, 'Мобилизация тазобедренного сустава', 'Специалист удерживает бедро и создаёт лёгкие тракционные и ротационные движения в тазобедренном суставе. Улучшает подвижность сустава, снимает блок в капсуле.', '', 4);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(9, 'Расслабление большой ягодичной мышцы', 'Специалист работает с большой ягодичной мышцей продольными и поперечными движениями, постепенно увеличивая глубину. Снимает хроническое напряжение, которое формируется при длительном сидении.', '', 1),
(9, 'Работа с грушевидной мышцей', 'Клиент лежит на животе. Специалист находит грушевидную мышцу (середина линии от крестца к большому вертелу) и создаёт точечное давление. Удержание до расслабления. Снимает синдром грушевидной мышцы, уменьшает боль по ходу седалищного нерва.', '', 2),
(9, 'Мобилизация крестцово-подвздошного сустава', 'Специалист укладывает руку на крестец и создаёт мягкий ротационный импульс в сторону КПС. Снимает блок в крестцово-подвздошном суставе.', '', 3),
(9, 'Расслабление средней ягодичной мышцы', 'Работа с зоной над большим вертелом. Продольные движения вдоль волокон средней ягодичной мышцы. Снимает напряжение, которое формируется при нарушении паттерна ходьбы.', '', 4);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(10, 'Расслабление двуглавой мышцы плеча', 'Мягкие продольные движения по передней поверхности плеча вдоль бицепса. Снимает напряжение сгибателей плеча, улучшает подвижность локтевого сустава.', '', 1),
(10, 'Работа с трёхглавой мышцей плеча', 'Продольные движения по задней поверхности плеча вдоль трицепса. Снимает напряжение разгибателей, которое накапливается при работе за компьютером.', '', 2),
(10, 'Мобилизация плечевого сустава', 'Лёгкие пассивные движения в плечевом суставе в безболезненном диапазоне. Улучшает подвижность, снимает мышечную защиту вокруг сустава.', '', 3);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(11, 'Расслабление двуглавой мышцы плеча', 'Мягкие продольные движения по передней поверхности плеча вдоль бицепса. Снимает напряжение сгибателей плеча, улучшает подвижность локтевого сустава.', '', 1),
(11, 'Работа с трёхглавой мышцей плеча', 'Продольные движения по задней поверхности плеча вдоль трицепса. Снимает напряжение разгибателей, которое накапливается при работе за компьютером.', '', 2),
(11, 'Мобилизация плечевого сустава', 'Лёгкие пассивные движения в плечевом суставе в безболезненном диапазоне. Улучшает подвижность, снимает мышечную защиту вокруг сустава.', '', 3);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(12, 'Расслабление сгибателей предплечья', 'Продольные движения по ладонной поверхности предплечья от запястья к локтю. Снимает напряжение сгибателей пальцев и запястья, актуально при работе с мышью и клавиатурой.', '', 1),
(12, 'Работа с разгибателями предплечья', 'Продольные движения по тыльной поверхности предплечья. Снимает напряжение разгибателей, помогает при эпикондилите.', '', 2),
(12, 'Мобилизация лучезапястного сустава', 'Специалист удерживает предплечье одной рукой, кисть другой и создаёт мягкие тракционные и ротационные движения в запястье. Снимает скованность в суставе.', '', 3);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(13, 'Расслабление сгибателей предплечья', 'Продольные движения по ладонной поверхности предплечья от запястья к локтю. Снимает напряжение сгибателей пальцев и запястья, актуально при работе с мышью и клавиатурой.', '', 1),
(13, 'Работа с разгибателями предплечья', 'Продольные движения по тыльной поверхности предплечья. Снимает напряжение разгибателей, помогает при эпикондилите.', '', 2),
(13, 'Мобилизация лучезапястного сустава', 'Специалист удерживает предплечье одной рукой, кисть другой и создаёт мягкие тракционные и ротационные движения в запястье. Снимает скованность в суставе.', '', 3);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(14, 'Расслабление четырёхглавой мышцы бедра', 'Продольные движения по передней поверхности бедра от паха к колену. Снимает напряжение квадрицепса, улучшает разгибание в коленном суставе.', '', 1),
(14, 'Работа с задней группой мышц бедра', 'Продольные движения по задней поверхности бедра вдоль бицепса бедра и полусухожильной мышцы. Снимает напряжение флексоров колена, помогает при боли в ягодице и подколенной ямке.', '', 2),
(14, 'Расслабление IT-тракта', 'Продольные движения по наружной поверхности бедра от вертела к колену. Снимает напряжение подвздошно-большеберцового тракта, актуально при боли в наружной части колена.', '', 3);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(15, 'Расслабление четырёхглавой мышцы бедра', 'Продольные движения по передней поверхности бедра от паха к колену. Снимает напряжение квадрицепса, улучшает разгибание в коленном суставе.', '', 1),
(15, 'Работа с задней группой мышц бедра', 'Продольные движения по задней поверхности бедра. Снимает напряжение флексоров колена.', '', 2),
(15, 'Расслабление IT-тракта', 'Продольные движения по наружной поверхности бедра. Снимает напряжение подвздошно-большеберцового тракта.', '', 3);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(16, 'Мобилизация надколенника', 'Специалист мягко смещает надколенник в четырёх направлениях — медиально, латерально, краниально, каудально. Улучшает скольжение надколенника, снимает напряжение удерживателей.', '', 1),
(16, 'Расслабление подколенной ямки', 'Мягкая работа с мягкими тканями подколенной ямки. Снимает напряжение задней капсулы коленного сустава, улучшает разгибание.', '', 2),
(16, 'Работа с точками крепления связок', 'Специалист работает с зонами крепления медиальной и латеральной коллатеральных связок. Улучшает питание и подвижность связочного аппарата коленного сустава.', '', 3);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(17, 'Мобилизация надколенника', 'Мягкое смещение надколенника в четырёх направлениях. Улучшает скольжение, снимает напряжение удерживателей.', '', 1),
(17, 'Расслабление подколенной ямки', 'Работа с мягкими тканями задней поверхности коленного сустава. Снимает напряжение задней капсулы.', '', 2),
(17, 'Работа с точками крепления связок', 'Работа с зонами крепления коллатеральных связок. Улучшает питание связочного аппарата.', '', 3);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(18, 'Расслабление икроножной мышцы', 'Продольные движения по задней поверхности голени от подколенной ямки к пятке. Снимает напряжение икроножной мышцы, помогает при судорогах и тяжести в ногах.', '', 1),
(18, 'Работа с камбаловидной мышцей', 'Специалист работает в глубину под икроножной мышцей. Снимает напряжение камбаловидной, улучшает венозный отток из голени.', '', 2),
(18, 'Расслабление передней большеберцовой мышцы', 'Продольные движения по передней поверхности голени вдоль большеберцовой мышцы. Снимает усталость от ходьбы, помогает при синдроме передней большеберцовой мышцы.', '', 3);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(19, 'Расслабление икроножной мышцы', 'Продольные движения по задней поверхности голени. Снимает напряжение икроножной мышцы.', '', 1),
(19, 'Работа с камбаловидной мышцей', 'Глубокая работа под икроножной мышцей. Улучшает венозный отток из голени.', '', 2),
(19, 'Расслабление передней большеберцовой мышцы', 'Продольные движения по передней поверхности голени. Снимает усталость и синдром передней большеберцовой мышцы.', '', 3);
INSERT INTO t_p84565078_code_expression_proj.lk_body_techniques (zone_id, title, description, video_url, sort_order) VALUES
(20, 'Расслабление подошвенной фасции', 'Специалист работает с подошвенной поверхностью стопы продольными движениями от пятки к пальцам. Снимает напряжение фасции, помогает при плантарном фасциите и усталости стоп.', '', 1),
(20, 'Мобилизация голеностопного сустава', 'Специалист удерживает голень и стопу и создаёт мягкие тракционные и ротационные движения в голеностопном суставе. Улучшает подвижность, снимает скованность.', '', 2),
(20, 'Работа с межплюсневыми мышцами', 'Специалист работает с тыльной поверхностью стопы в промежутках между плюсневыми костями. Снимает напряжение, которое накапливается при длительном стоянии.', '', 3),
(20, 'Расслабление ахиллова сухожилия', 'Мягкое продольное движение вдоль ахиллова сухожилия от пятки к мышечно-сухожильному переходу. Снимает напряжение, улучшает эластичность сухожилия.', '', 4);
